def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    dangerous_prev = []
    needy_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 0) <= 4:
                needy_count += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if float(bid) >= 80:
                    dangerous_prev.append(float(bid))

    if not alive_opponents:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0
    tightness = 1.0 - scarcity

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water >= 2:
        urgency += 3
    elif no_water >= 1:
        urgency += 1

    if supply <= 17:
        urgency += 2
    elif supply <= 20:
        urgency += 1

    if needy_count >= 2:
        urgency += 1

    if budget < DAILY_SALARY * 1.2:
        urgency -= 1

    if urgency <= 0:
        base = 14.0 + 8.0 * tightness
        if highest_prev >= 120 and hp > 4:
            base = min(base, 22.0)
        bid = base
    elif urgency == 1:
        bid = max(24.0, avg_prev * 0.45 + 6.0, highest_prev * 0.28 + 8.0)
    elif urgency == 2:
        bid = max(38.0, avg_prev * 0.62 + 8.0, highest_prev * 0.52 + 6.0)
    elif urgency == 3:
        bid = max(55.0, highest_prev + 2.0 if highest_prev > 0 else 60.0)
    else:
        bid = max(72.0, highest_prev + 3.0 if highest_prev > 0 else 78.0)

    if dangerous_prev and hp > 4 and no_water == 0 and supply >= 20:
        bid = min(bid, 36.0)

    if hp <= 2 or no_water >= 2:
        bid = max(bid, highest_prev + 3.0 if highest_prev > 0 else 75.0)

    reserve = 0.0
    if hp > 4 and no_water == 0:
        reserve = 18.0
    elif hp > 2:
        reserve = 8.0

    max_affordable = max(0.0, budget - reserve)
    if max_affordable <= 0:
        return float(min(budget, 6.0))

    bid = min(bid, max_affordable)
    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for k, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((k, o))

    # If everyone is dead, conserve.
    if not alive_opps:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Read yesterday bids to infer who is pressuring.
    yesterday_bids = []
    for agent_id, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Estimate how much water is likely needed to avoid worsening.
    # If supply is low, we must secure water; if high, we can bid less.
    supply_frac = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_frac = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    if supply_frac < 0.0:
        supply_frac = 0.0
    if supply_frac > 1.0:
        supply_frac = 1.0

    # Base bid: mid level to compete without matching Cindy's extreme bids.
    # Scarce supply -> higher bid; abundant -> lower.
    scarce_factor = 1.0 - supply_frac
    base = DAILY_SALARY * (0.45 + 0.25 * scarce_factor)  # ~40-67

    # Pressure adjustment: if someone already paid very high yesterday, don't chase fully.
    # Instead, bid just enough to beat typical mid bids but below extreme max.
    if highest_prev_bid >= DAILY_SALARY * 1.3:
        # Cindy-like pressure: we cap below her level.
        base = min(base, DAILY_SALARY * 0.75)

    # Urgency from our HP / consecutive no-water days.
    if hp <= 2.0 or no_water_days >= 2:
        urgency = DAILY_SALARY * 0.85
    elif hp <= 4.0 or no_water_days >= 1:
        urgency = DAILY_SALARY * 0.65
    else:
        urgency = DAILY_SALARY * 0.55

    # Choose final bid: take max of base and urgency, but keep under a safety cap.
    # Safety cap prevents catastrophic spending.
    safety_cap = min(budget, DAILY_SALARY * (0.95 if hp <= 2.0 else 0.7))

    bid = max(base, urgency)
    if bid > safety_cap:
        bid = safety_cap

    # Ensure non-negative and not exceeding budget.
    if bid < 0.0:
        bid = 0.0
    if bid > budget:
        bid = budget

    return float(bid)

